window.LEARN={"cards": [{"id": "r0", "chapter": 1, "en": "Care for a New Plant", "zh": "照顾新植物", "word": "roots", "wordzh": "根", "art": "plant", "variants": [{"en": "A basil plant has dry soil. Which part takes in water when we water the soil?", "zh": "罗勒土壤干了，浇水后哪个部位吸收水？", "options": ["Roots", "Flowers"], "answer": 0, "fact": "Roots take in water from soil.", "factzh": "根从土壤吸收水。"}, {"en": "A young tomato plant is watered at its roots. Which part carries water upward?", "zh": "给番茄幼苗的根部浇水后，哪个部位向上运输水？", "options": ["Stem", "Fruit"], "answer": 0, "fact": "The stem supports the plant and carries water.", "factzh": "茎支撑植物并运输水。"}]}, {"id": "r1", "chapter": 1, "en": "A Fair Light Test", "zh": "公平的光照试验", "word": "compare", "wordzh": "比较", "art": "plant", "variants": [{"en": "Two matching seedlings have the same water and soil. Only the light direction changes. What are we testing?", "zh": "两株相似幼苗水土相同，只改光的方向，在测什么？", "options": ["A response to light", "A response to different pots"], "answer": 0, "fact": "Change only the light direction to investigate this response.", "factzh": "只改光的方向来研究响应。"}, {"en": "A lamp moves to the right of a young shoot. What is a reasonable prediction over time?", "zh": "灯移到幼嫩茎右侧，经过一段时间可怎样预测？", "options": ["It may grow toward the light.", "It instantly jumps into the lamp."], "answer": 0, "fact": "Many young shoots gradually grow toward light.", "factzh": "许多幼茎逐渐向光生长。"}]}, {"id": "r2", "chapter": 2, "en": "Body Evidence", "zh": "身体证据", "word": "backbone", "wordzh": "脊柱", "art": "frog", "variants": [{"en": "A dolphin swims, but it has a backbone. Which group fits?", "zh": "海豚会游泳，但有脊柱，属于哪组？", "options": ["Vertebrate", "Invertebrate"], "answer": 0, "fact": "A backbone is evidence for the vertebrate group.", "factzh": "脊柱是归入脊椎动物的依据。"}, {"en": "A snail crawls and has no backbone. Which group fits?", "zh": "蜗牛爬行且无脊柱，属于哪组？", "options": ["Vertebrate", "Invertebrate"], "answer": 1, "fact": "A snail is an invertebrate.", "factzh": "蜗牛是无脊椎动物。"}]}, {"id": "r3", "chapter": 2, "en": "Growing and Changing", "zh": "成长与变化", "word": "life cycle", "wordzh": "生命周期", "art": "frog", "variants": [{"en": "A caterpillar stops feeding and forms a pupa. What can come next?", "zh": "毛毛虫停止进食并化蛹，之后可能是什么？", "options": ["An adult butterfly", "A frog egg"], "answer": 0, "fact": "An adult butterfly can emerge from the pupa.", "factzh": "蛹可羽化出成蝶。"}, {"en": "A tadpole has growing legs and a shrinking tail. What stage is it approaching?", "zh": "蝌蚪长腿、尾巴缩短，接近哪个阶段？", "options": ["Froglet", "Butterfly pupa"], "answer": 0, "fact": "It is developing toward a froglet.", "factzh": "它在向幼蛙阶段发育。"}]}, {"id": "r4", "chapter": 3, "en": "Drainage Records", "zh": "排水记录", "word": "evidence", "wordzh": "证据", "art": "rock", "variants": [{"en": "Same cups, soil amounts, water, and time. A drains 40 mL; B drains 15 mL. Which drains more?", "zh": "杯、土量、水量、时间相同。A流出40毫升，B15毫升，谁更多？", "options": ["A", "B"], "answer": 0, "fact": "40 mL is more than 15 mL under these test conditions.", "factzh": "在该条件下40毫升大于15毫升。"}, {"en": "Same conditions. C drains 18 mL; D drains 48 mL. Which drains less?", "zh": "相同条件，C流出18毫升，D48毫升，谁更少？", "options": ["C", "D"], "answer": 0, "fact": "18 mL is less than 48 mL.", "factzh": "18毫升小于48毫升。"}]}, {"id": "r5", "chapter": 3, "en": "Choose an Observation", "zh": "选择观察方法", "word": "observe", "wordzh": "观察", "art": "rock", "variants": [{"en": "You see a rock photo. Can you measure its actual mass from this picture alone?", "zh": "只看岩石照片能测出真实质量吗？", "options": ["No. We need a suitable measuring tool.", "Yes. A darker color tells its mass."], "answer": 0, "fact": "A photo alone does not measure actual mass.", "factzh": "仅靠照片不能测出真实质量。"}, {"en": "Two real stones look similar. How could you compare how rough they feel?", "zh": "两块真石头看起来相似，怎样比较粗糙触感？", "options": ["Touch their surfaces carefully.", "Guess from the names."], "answer": 0, "fact": "Touch provides evidence about how a surface feels.", "factzh": "触摸可提供表面触感证据。"}]}, {"id": "r6", "chapter": 4, "en": "What Can a Fossil Tell Us?", "zh": "化石能告诉我们什么", "word": "trace", "wordzh": "遗迹", "art": "fossil", "variants": [{"en": "A rock preserves a trail of footprints. What is supported?", "zh": "岩石保存一串足迹，支持什么？", "options": ["An animal moved there.", "We know its exact skin color."], "answer": 0, "fact": "Footprints record activity, but not exact skin color.", "factzh": "足迹记录活动，但不记录确切肤色。"}, {"en": "A leaf shape is preserved in rock. What can you observe directly?", "zh": "岩石保存叶形，能直接观察什么？", "options": ["The outline of the leaf", "The exact smell of the living plant"], "answer": 0, "fact": "The preserved outline is visible evidence.", "factzh": "保存的轮廓是可见证据。"}]}, {"id": "r7", "chapter": 4, "en": "Read the Layers", "zh": "阅读岩层", "word": "older", "wordzh": "更古老", "art": "fossil", "variants": [{"en": "In undisturbed layers, shell rock is below leaf rock. Which was deposited first?", "zh": "未扰动岩层中贝壳层在叶层下方，哪层先沉积？", "options": ["Shell layer", "Leaf layer"], "answer": 0, "fact": "The lower layer was deposited first in this undisturbed sequence.", "factzh": "此未扰动岩层中下层先沉积。"}, {"en": "Fish fossils occur above a lower shell layer. The layers are not overturned. Which layer is younger?", "zh": "鱼化石层在贝壳层上方，未倒转，哪层更年轻？", "options": ["Fish layer", "Shell layer"], "answer": 0, "fact": "The upper layer is younger in this sequence.", "factzh": "该岩层序列中上层较年轻。"}]}, {"id": "r8", "chapter": 5, "en": "Give Materials Another Use", "zh": "再用材料", "word": "reuse", "wordzh": "再利用", "art": "wheel", "variants": [{"en": "A clean, sturdy box can hold craft supplies. Which action is reuse?", "zh": "干净结实的盒子可以装手工用品，哪个是再利用？", "options": ["Use it for storage.", "Buy a new box and throw this one away."], "answer": 0, "fact": "Reusing an item can reduce the need for a new one.", "factzh": "再利用可以减少新物品需求。"}, {"en": "A notebook still has blank pages. What reduces paper waste?", "zh": "本子还有空白页，怎样减少纸张浪费？", "options": ["Use the blank pages.", "Throw it away now."], "answer": 0, "fact": "Use the remaining pages before buying another notebook.", "factzh": "用完剩余页面再买新本子。"}]}, {"id": "r9", "chapter": 5, "en": "Trace a Product", "zh": "追踪用品来源", "word": "resource", "wordzh": "资源", "art": "plant", "variants": [{"en": "A wooden spoon and a paper bag can both begin with which resource?", "zh": "木勺和纸袋都可能源自什么资源？", "options": ["Trees", "Coal only"], "answer": 0, "fact": "Wood and much paper come from trees.", "factzh": "木材和许多纸张来自树木。"}, {"en": "Many conventional plastic bottles use raw materials from which resource?", "zh": "许多常规塑料瓶使用哪种资源作原料？", "options": ["Petroleum", "Wool"], "answer": 0, "fact": "Petroleum supplies raw materials for many conventional plastics.", "factzh": "石油为许多常规塑料提供原料。"}]}, {"id": "r10", "chapter": 6, "en": "Compare Two Deliveries", "zh": "比较两次运输", "word": "speed", "wordzh": "速度", "art": "wheel", "variants": [{"en": "Both carts travel for 6 seconds. A goes 12 units, B goes 18. Which has greater average speed?", "zh": "两车都走6秒，A12单位，B18单位，谁平均速度更大？", "options": ["A", "B"], "answer": 1, "fact": "For the same time, B travels farther.", "factzh": "相同时间B走得更远。"}, {"en": "Both carts travel 24 units. A takes 4 seconds, B takes 8. Which has greater average speed?", "zh": "两车都走24单位，A4秒，B8秒，谁平均速度更大？", "options": ["A", "B"], "answer": 0, "fact": "For the same distance, A takes less time.", "factzh": "相同路程A用时更少。"}]}, {"id": "r11", "chapter": 6, "en": "Revise the Delivery Plan", "zh": "修改运输计划", "word": "predict", "wordzh": "预测", "art": "wheel", "variants": [{"en": "A cart goes beyond the station. Keep the track and cart fixed. What could you test next?", "zh": "小车超过车站，保持车和路面，下一次可测什么？", "options": ["Earlier braking", "Change every condition"], "answer": 0, "fact": "Earlier braking is a relevant change to test.", "factzh": "更早制动是针对问题的可测试改变。"}, {"en": "A cart stops before the station. What is a useful prediction to test?", "zh": "小车未到站就停止，可测试什么预测？", "options": ["Later braking may bring it closer.", "Its color must make it stop early."], "answer": 0, "fact": "Test a relevant change and compare the result.", "factzh": "测试相关条件的改变并比较结果。"}]}, {"id": "r12", "chapter": 7, "en": "A Recycling Magnet", "zh": "回收站磁铁", "word": "attract", "wordzh": "吸引", "art": "magnet", "variants": [{"en": "A classroom magnet lifts iron nails but not aluminum pieces. What can it separate here?", "zh": "课堂磁铁提起铁钉但不提起铝片，这里能分开什么？", "options": ["Iron from aluminum", "Every kind of plastic"], "answer": 0, "fact": "Use the observed magnetic response to separate these materials.", "factzh": "依据观察到的磁性响应分离这些材料。"}, {"en": "Two magnet ends marked N face each other. What should happen?", "zh": "两磁铁N端相对，会怎样？", "options": ["Repel", "Attract"], "answer": 0, "fact": "Like poles repel. Unlike poles attract.", "factzh": "同名磁极排斥，异名磁极吸引。"}]}, {"id": "r13", "chapter": 7, "en": "Change a Sound Signal", "zh": "改变声音讯号", "word": "pitch", "wordzh": "音高", "art": "sound", "variants": [{"en": "Keep vibration size the same. Change from 250 to 500 vibrations per second. What changes?", "zh": "振幅不变，从每秒250次变500次，什么改变？", "options": ["Pitch becomes higher.", "Gravity disappears."], "answer": 0, "fact": "Faster vibrations produce a higher pitch.", "factzh": "更快振动产生更高音调。"}, {"en": "Keep vibration frequency fixed, but make the vibration larger. What changes in this model?", "zh": "频率不变，振幅增大，模型中什么变化？", "options": ["The tone gets louder.", "The pitch must get lower."], "answer": 0, "fact": "A larger vibration amplitude increases this tone’s loudness.", "factzh": "较大振幅使此声音更响。"}]}], "sentences": [{"id": "s0", "chapter": 1, "category": "Describe", "art": "plant", "parts": ["Roots take in", "water and minerals", "from the soil."], "zh": "根从土壤吸收水和矿物质。", "options": ["Roots absorb water.", "Fruit absorbs all the soil water."], "answer": 0, "gap": "A ___ supports the plant and carries water.", "gapzh": "哪一部位支撑植物并运输水？", "gapoptions": ["stem", "seed coat"], "gapanswer": 0, "full": "A stem supports the plant and carries water.", "fullzh": "茎支撑植物并运输水。"}, {"id": "s1", "chapter": 1, "category": "Predict", "art": "plant", "parts": ["If the light moves,", "the young shoot may grow", "toward it."], "zh": "如果光源移动，幼茎可能朝它生长。", "options": ["A prediction about future growth", "A record of a rock’s mass"], "answer": 0, "gap": "I keep water and soil the ___ when testing light.", "gapzh": "研究光照时，水和土壤保持怎样？", "gapoptions": ["same", "opposite"], "gapanswer": 0, "full": "I keep water and soil the same when testing light.", "fullzh": "研究光照时，我保持水和土壤相同。"}, {"id": "s2", "chapter": 2, "category": "Explain", "art": "frog", "parts": ["A frog has a backbone,", "so it is", "a vertebrate."], "zh": "青蛙有脊柱，因此是脊椎动物。", "options": ["Classification using body evidence", "Classification using favorite colors"], "answer": 0, "gap": "A snail has no backbone, so it is an ___.", "gapzh": "蜗牛没有脊柱，因此属于哪一类？", "gapoptions": ["invertebrate", "vertebrate"], "gapanswer": 0, "full": "A snail has no backbone, so it is an invertebrate.", "fullzh": "蜗牛没有脊柱，因此是无脊椎动物。"}, {"id": "s3", "chapter": 2, "category": "Describe", "art": "frog", "parts": ["A caterpillar becomes a pupa", "before it develops", "into an adult butterfly."], "zh": "毛毛虫先化蛹，再发育为成蝶。", "options": ["A sequence of life stages", "A sequence of rock layers"], "answer": 0, "gap": "A tadpole develops into a ___.", "gapzh": "蝌蚪接下来发育成什么？", "gapoptions": ["froglet", "seedling"], "gapanswer": 0, "full": "A tadpole develops into a froglet.", "fullzh": "蝌蚪发育成幼蛙。"}, {"id": "s4", "chapter": 3, "category": "Compare", "art": "rock", "parts": ["Sample A drains more water", "than sample B", "in this test."], "zh": "在这次试验中，A流出水量比B多。", "options": ["Comparing measured results", "Saying A is best for every plant"], "answer": 0, "gap": "For a fair soil test, use the same ___ of water.", "gapzh": "公平比较土样时，加水什么应相同？", "gapoptions": ["amount", "color of cup"], "gapanswer": 0, "full": "For a fair soil test, use the same amount of water.", "fullzh": "公平比较土样时，要用相同水量。"}, {"id": "s5", "chapter": 3, "category": "Explain", "art": "rock", "parts": ["I observe the surface", "and use a tool", "to measure the mass."], "zh": "我观察表面，并用工具测量质量。", "options": ["Choosing evidence and a measuring method", "Guessing every property from color"], "answer": 0, "gap": "I use a ___ to compare mass, not just a photograph.", "gapzh": "比较质量应使用什么，而非只看照片？", "gapoptions": ["balance", "lamp"], "gapanswer": 0, "full": "I use a balance to compare mass, not just a photograph.", "fullzh": "我用天平比较质量，不只看照片。"}, {"id": "s6", "chapter": 4, "category": "Explain", "art": "fossil", "parts": ["A footprint is evidence", "of an animal’s activity", "in the past."], "zh": "足迹是动物过去活动的证据。", "options": ["A conclusion supported by a trace", "An exact record of skin color"], "answer": 0, "gap": "The fossil does not tell us every ___.", "gapzh": "化石不能告诉我们每个什么？", "gapoptions": ["detail", "clue"], "gapanswer": 0, "full": "The fossil does not tell us every detail.", "fullzh": "化石不能告诉我们所有细节。"}, {"id": "s7", "chapter": 4, "category": "Compare", "art": "fossil", "parts": ["In undisturbed layers,", "the lower layer", "is older."], "zh": "在未扰动岩层中，下层更古老。", "options": ["Comparing relative ages", "Finding an exact age in years"], "answer": 0, "gap": "We need more evidence for an ___ age in years.", "gapzh": "要知道具体多少年的年龄，需要更多证据。", "gapoptions": ["exact", "older"], "gapanswer": 0, "full": "We need more evidence for an exact age in years.", "fullzh": "要知道具体多少年的年龄，我们需要更多证据。"}, {"id": "s8", "chapter": 5, "category": "Explain", "art": "wheel", "parts": ["Reusing a useful item", "can reduce the need", "for new materials."], "zh": "再用有用物品可以减少新材料需求。", "options": ["Explaining a resource-saving choice", "Claiming that nothing ever wears out"], "answer": 0, "gap": "A loose shelf screw may need ___ before reuse.", "gapzh": "架子螺丝松了，再用前可能需要什么？", "gapoptions": ["repair", "more paint only"], "gapanswer": 0, "full": "A loose shelf screw may need repair before reuse.", "fullzh": "架子上的松螺丝可能需要先修理再使用。"}, {"id": "s9", "chapter": 5, "category": "Describe", "art": "plant", "parts": ["Wood can be used", "for furniture, buildings,", "and paper."], "zh": "木材可用于家具、建筑和造纸。", "options": ["Several uses of one resource", "Only one possible use for wood"], "answer": 0, "gap": "Coal can be burned to generate ___.", "gapzh": "煤可以燃烧用于产生什么？", "gapoptions": ["electricity", "new trees"], "gapanswer": 0, "full": "Coal can be burned to generate electricity.", "fullzh": "煤可以燃烧发电。"}, {"id": "s10", "chapter": 6, "category": "Compare", "art": "wheel", "parts": ["For the same distance,", "the faster cart", "takes less time."], "zh": "相同路程，更快的车用时更少。", "options": ["Comparing time for equal distances", "Comparing who starts first"], "answer": 0, "gap": "For equal time, compare the ___ traveled.", "gapzh": "相同时间应比较行驶的什么？", "gapoptions": ["distance", "color"], "gapanswer": 0, "full": "For equal time, compare the distance traveled.", "fullzh": "相同时间应比较行驶路程。"}, {"id": "s11", "chapter": 6, "category": "Predict", "art": "wheel", "parts": ["If I brake earlier,", "the cart may stop", "closer to the target."], "zh": "如果更早制动，小车可能更靠近目标停止。", "options": ["A prediction to test", "A guarantee for every cart"], "answer": 0, "gap": "After testing, I compare my prediction with the ___.", "gapzh": "试验后将预测与什么比较？", "gapoptions": ["result", "favorite color"], "gapanswer": 0, "full": "After testing, I compare my prediction with the result.", "fullzh": "试验后，我把预测与结果比较。"}, {"id": "s12", "chapter": 7, "category": "Explain", "art": "magnet", "parts": ["A magnet attracts iron.", "It does not attract", "every metal."], "zh": "磁铁吸引铁，但不吸引所有金属。", "options": ["Using evidence to limit a claim", "Saying all metals behave alike"], "answer": 0, "gap": "Unlike magnetic poles ___.", "gapzh": "异名磁极怎样作用？", "gapoptions": ["attract", "repel"], "gapanswer": 0, "full": "Unlike magnetic poles attract.", "fullzh": "异名磁极相互吸引。"}, {"id": "s13", "chapter": 7, "category": "Predict", "art": "sound", "parts": ["If the vibrations are faster,", "the sound has", "a higher pitch."], "zh": "如果振动更快，声音音调更高。", "options": ["Predicting a change in pitch", "Predicting a change in leaf color"], "answer": 0, "gap": "At the same frequency, larger vibrations make a tone ___.", "gapzh": "频率相同，较大振幅使声音怎样？", "gapoptions": ["louder", "higher in pitch"], "gapanswer": 0, "full": "At the same frequency, larger vibrations make a tone louder.", "fullzh": "相同频率下，较大振幅使声音更响。"}], "family": [{"id": "f0", "en": "Leaf Detectives", "zh": "叶片侦探", "art": "plant", "enprompt": "Compare two fallen leaves. Record their shapes and one visible difference.", "zhprompt": "比较两片落叶，记录形状与一个可见差异。", "question": "What can you see? What would require touching?", "questionzh": "哪些可直接看到，哪些需要触摸？"}, {"id": "f1", "en": "Animal Watch", "zh": "动物观察", "art": "frog", "enprompt": "Watch an animal from a distance. Record an action and separate what you see from what you guess.", "zhprompt": "远处观察动物，记录一个动作，区分看到的与猜测的。", "question": "What is your observation? What is still unknown?", "questionzh": "观察到了什么，还有什么未知？"}, {"id": "f2", "en": "Material Survey", "zh": "材料调查", "art": "rock", "enprompt": "Choose three familiar household objects. Describe their visible materials and how the materials suit the job.", "zhprompt": "选三件熟悉的日用品，描述可辨认的材料及其与用途的关系。", "question": "Which material is useful for this task? Why?", "questionzh": "材料为什么适合这个用途？"}, {"id": "f3", "en": "Evidence Detective", "zh": "证据侦探", "art": "fossil", "enprompt": "Look at a shoe print in sand or a photograph of one. Record two visible features.", "zhprompt": "观察沙地鞋印或鞋印照片，记录两个可见特征。", "question": "What can the print tell you? What can it not tell you?", "questionzh": "鞋印能告诉你什么，不能告诉你什么？"}, {"id": "f4", "en": "Reuse at Home", "zh": "家中再用", "art": "wheel", "enprompt": "Find a clean, safe item that can be reused. Ask an adult before changing its use.", "zhprompt": "找一件干净安全的可再用物品，改变用途前问家长。", "question": "What new use did you choose? What new material could it save?", "questionzh": "选择了什么新用途，可能节省什么新材料？"}, {"id": "f5", "en": "A Gentle Ramp Test", "zh": "轻柔斜坡试验", "art": "ramp", "enprompt": "With an adult, use a low cardboard ramp and a toy car. Keep the start and car the same; compare two surfaces.", "zhprompt": "与家长用低纸板斜坡和玩具车，保持起点与车相同，比较两种表面。", "question": "What did you keep the same? Where did the car stop?", "questionzh": "保持什么相同，小车停在哪里？"}, {"id": "f6", "en": "Sound Around Us", "zh": "身边的声音", "art": "sound", "enprompt": "Make a gentle humming sound. Notice the vibration at your throat. Try a higher and a lower pitch at comfortable volume.", "zhprompt": "轻声哼鸣，感受喉部振动，用舒适音量试高音和低音。", "question": "How was higher different from louder?", "questionzh": "更高和更响有什么不同？"}], "audio": {"learn-r0-word": "roots", "learn-r0-0": "A basil plant has dry soil. Which part takes in water when we water the soil? A. Roots B. Flowers", "learn-r0-0-fact": "Roots take in water from soil.", "learn-r0-1": "A young tomato plant is watered at its roots. Which part carries water upward? A. Stem B. Fruit", "learn-r0-1-fact": "The stem supports the plant and carries water.", "learn-r1-word": "compare", "learn-r1-0": "Two matching seedlings have the same water and soil. Only the light direction changes. What are we testing? A. A response to light B. A response to different pots", "learn-r1-0-fact": "Change only the light direction to investigate this response.", "learn-r1-1": "A lamp moves to the right of a young shoot. What is a reasonable prediction over time? A. It may grow toward the light. B. It instantly jumps into the lamp.", "learn-r1-1-fact": "Many young shoots gradually grow toward light.", "learn-r2-word": "backbone", "learn-r2-0": "A dolphin swims, but it has a backbone. Which group fits? A. Vertebrate B. Invertebrate", "learn-r2-0-fact": "A backbone is evidence for the vertebrate group.", "learn-r2-1": "A snail crawls and has no backbone. Which group fits? A. Vertebrate B. Invertebrate", "learn-r2-1-fact": "A snail is an invertebrate.", "learn-r3-word": "life cycle", "learn-r3-0": "A caterpillar stops feeding and forms a pupa. What can come next? A. An adult butterfly B. A frog egg", "learn-r3-0-fact": "An adult butterfly can emerge from the pupa.", "learn-r3-1": "A tadpole has growing legs and a shrinking tail. What stage is it approaching? A. Froglet B. Butterfly pupa", "learn-r3-1-fact": "It is developing toward a froglet.", "learn-r4-word": "evidence", "learn-r4-0": "Same cups, soil amounts, water, and time. A drains 40 mL; B drains 15 mL. Which drains more? A. A B. B", "learn-r4-0-fact": "40 mL is more than 15 mL under these test conditions.", "learn-r4-1": "Same conditions. C drains 18 mL; D drains 48 mL. Which drains less? A. C B. D", "learn-r4-1-fact": "18 mL is less than 48 mL.", "learn-r5-word": "observe", "learn-r5-0": "You see a rock photo. Can you measure its actual mass from this picture alone? A. No. We need a suitable measuring tool. B. Yes. A darker color tells its mass.", "learn-r5-0-fact": "A photo alone does not measure actual mass.", "learn-r5-1": "Two real stones look similar. How could you compare how rough they feel? A. Touch their surfaces carefully. B. Guess from the names.", "learn-r5-1-fact": "Touch provides evidence about how a surface feels.", "learn-r6-word": "trace", "learn-r6-0": "A rock preserves a trail of footprints. What is supported? A. An animal moved there. B. We know its exact skin color.", "learn-r6-0-fact": "Footprints record activity, but not exact skin color.", "learn-r6-1": "A leaf shape is preserved in rock. What can you observe directly? A. The outline of the leaf B. The exact smell of the living plant", "learn-r6-1-fact": "The preserved outline is visible evidence.", "learn-r7-word": "older", "learn-r7-0": "In undisturbed layers, shell rock is below leaf rock. Which was deposited first? A. Shell layer B. Leaf layer", "learn-r7-0-fact": "The lower layer was deposited first in this undisturbed sequence.", "learn-r7-1": "Fish fossils occur above a lower shell layer. The layers are not overturned. Which layer is younger? A. Fish layer B. Shell layer", "learn-r7-1-fact": "The upper layer is younger in this sequence.", "learn-r8-word": "reuse", "learn-r8-0": "A clean, sturdy box can hold craft supplies. Which action is reuse? A. Use it for storage. B. Buy a new box and throw this one away.", "learn-r8-0-fact": "Reusing an item can reduce the need for a new one.", "learn-r8-1": "A notebook still has blank pages. What reduces paper waste? A. Use the blank pages. B. Throw it away now.", "learn-r8-1-fact": "Use the remaining pages before buying another notebook.", "learn-r9-word": "resource", "learn-r9-0": "A wooden spoon and a paper bag can both begin with which resource? A. Trees B. Coal only", "learn-r9-0-fact": "Wood and much paper come from trees.", "learn-r9-1": "Many conventional plastic bottles use raw materials from which resource? A. Petroleum B. Wool", "learn-r9-1-fact": "Petroleum supplies raw materials for many conventional plastics.", "learn-r10-word": "speed", "learn-r10-0": "Both carts travel for 6 seconds. A goes 12 units, B goes 18. Which has greater average speed? A. A B. B", "learn-r10-0-fact": "For the same time, B travels farther.", "learn-r10-1": "Both carts travel 24 units. A takes 4 seconds, B takes 8. Which has greater average speed? A. A B. B", "learn-r10-1-fact": "For the same distance, A takes less time.", "learn-r11-word": "predict", "learn-r11-0": "A cart goes beyond the station. Keep the track and cart fixed. What could you test next? A. Earlier braking B. Change every condition", "learn-r11-0-fact": "Earlier braking is a relevant change to test.", "learn-r11-1": "A cart stops before the station. What is a useful prediction to test? A. Later braking may bring it closer. B. Its color must make it stop early.", "learn-r11-1-fact": "Test a relevant change and compare the result.", "learn-r12-word": "attract", "learn-r12-0": "A classroom magnet lifts iron nails but not aluminum pieces. What can it separate here? A. Iron from aluminum B. Every kind of plastic", "learn-r12-0-fact": "Use the observed magnetic response to separate these materials.", "learn-r12-1": "Two magnet ends marked N face each other. What should happen? A. Repel B. Attract", "learn-r12-1-fact": "Like poles repel. Unlike poles attract.", "learn-r13-word": "pitch", "learn-r13-0": "Keep vibration size the same. Change from 250 to 500 vibrations per second. What changes? A. Pitch becomes higher. B. Gravity disappears.", "learn-r13-0-fact": "Faster vibrations produce a higher pitch.", "learn-r13-1": "Keep vibration frequency fixed, but make the vibration larger. What changes in this model? A. The tone gets louder. B. The pitch must get lower.", "learn-r13-1-fact": "A larger vibration amplitude increases this tone’s loudness.", "learn-s0": "Roots take in water and minerals from the soil.", "learn-s0-gap": "A blank supports the plant and carries water. stem. seed coat", "learn-s0-full": "A stem supports the plant and carries water.", "learn-s1": "If the light moves, the young shoot may grow toward it.", "learn-s1-gap": "I keep water and soil the blank when testing light. same. opposite", "learn-s1-full": "I keep water and soil the same when testing light.", "learn-s2": "A frog has a backbone, so it is a vertebrate.", "learn-s2-gap": "A snail has no backbone, so it is an blank. invertebrate. vertebrate", "learn-s2-full": "A snail has no backbone, so it is an invertebrate.", "learn-s3": "A caterpillar becomes a pupa before it develops into an adult butterfly.", "learn-s3-gap": "A tadpole develops into a blank. froglet. seedling", "learn-s3-full": "A tadpole develops into a froglet.", "learn-s4": "Sample A drains more water than sample B in this test.", "learn-s4-gap": "For a fair soil test, use the same blank of water. amount. color of cup", "learn-s4-full": "For a fair soil test, use the same amount of water.", "learn-s5": "I observe the surface and use a tool to measure the mass.", "learn-s5-gap": "I use a blank to compare mass, not just a photograph. balance. lamp", "learn-s5-full": "I use a balance to compare mass, not just a photograph.", "learn-s6": "A footprint is evidence of an animal’s activity in the past.", "learn-s6-gap": "The fossil does not tell us every blank. detail. clue", "learn-s6-full": "The fossil does not tell us every detail.", "learn-s7": "In undisturbed layers, the lower layer is older.", "learn-s7-gap": "We need more evidence for an blank age in years. exact. older", "learn-s7-full": "We need more evidence for an exact age in years.", "learn-s8": "Reusing a useful item can reduce the need for new materials.", "learn-s8-gap": "A loose shelf screw may need blank before reuse. repair. more paint only", "learn-s8-full": "A loose shelf screw may need repair before reuse.", "learn-s9": "Wood can be used for furniture, buildings, and paper.", "learn-s9-gap": "Coal can be burned to generate blank. electricity. new trees", "learn-s9-full": "Coal can be burned to generate electricity.", "learn-s10": "For the same distance, the faster cart takes less time.", "learn-s10-gap": "For equal time, compare the blank traveled. distance. color", "learn-s10-full": "For equal time, compare the distance traveled.", "learn-s11": "If I brake earlier, the cart may stop closer to the target.", "learn-s11-gap": "After testing, I compare my prediction with the blank. result. favorite color", "learn-s11-full": "After testing, I compare my prediction with the result.", "learn-s12": "A magnet attracts iron. It does not attract every metal.", "learn-s12-gap": "Unlike magnetic poles blank. attract. repel", "learn-s12-full": "Unlike magnetic poles attract.", "learn-s13": "If the vibrations are faster, the sound has a higher pitch.", "learn-s13-gap": "At the same frequency, larger vibrations make a tone blank. louder. higher in pitch", "learn-s13-full": "At the same frequency, larger vibrations make a tone louder.", "learn-f0": "Compare two fallen leaves. Record their shapes and one visible difference. What can you see? What would require touching?", "learn-f1": "Watch an animal from a distance. Record an action and separate what you see from what you guess. What is your observation? What is still unknown?", "learn-f2": "Choose three familiar household objects. Describe their visible materials and how the materials suit the job. Which material is useful for this task? Why?", "learn-f3": "Look at a shoe print in sand or a photograph of one. Record two visible features. What can the print tell you? What can it not tell you?", "learn-f4": "Find a clean, safe item that can be reused. Ask an adult before changing its use. What new use did you choose? What new material could it save?", "learn-f5": "With an adult, use a low cardboard ramp and a toy car. Keep the start and car the same; compare two surfaces. What did you keep the same? Where did the car stop?", "learn-f6": "Make a gentle humming sound. Notice the vibration at your throat. Try a higher and a lower pitch at comfortable volume. How was higher different from louder?", "learn-greenhouse": "Move the lamp to one side. Compare how a young shoot may grow toward light over time. This is a simplified model, not a live plant.", "learn-greenhouse-trial0": "Lamp on the left. Over time, the young shoot may bend left toward the lamp.", "learn-greenhouse-trial1": "Lamp on the right. Over time, the young shoot may bend right toward the lamp."}};
